import {useState, useEffect} from 'react';
import {ApiProfessor} from "../api";

const useProfessor = () => {
    const [state, setState] = useState();
    useEffect(() => {
        setProfessor();
    },[]);

    const setProfessor = async (professorEndpoint) => {
        const professor = await ApiProfessor(professorEndpoint);
        setState(professor);
    };
    return [state, setProfessor];
};

export default useProfessor;
